package cn.course.community;
import java.util.*;import java.time.Instant;import java.math.BigDecimal;
import com.fasterxml.jackson.databind.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:rubric-test;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1","app.seed=true","app.seed-password=TestOnly!2026Long"}) @AutoConfigureMockMvc @Transactional
class RubricServiceTest {
 @Autowired RubricService r;@Autowired Store s;@Autowired CommunityService domain;@Autowired ObjectMapper json;@Autowired MockMvc mvc;
 long teacher(){return s.uid("teacher@example.test");}long student(){return s.uid("student@example.test");}long id(Map<String,Object> row){return s.id(row,"id");}
 Map<String,Object> draft(){return r.create(1,teacher(),0L);}int catalog(){return ((Number)r.list(1,teacher()).get("catalogRevision")).intValue();}
 RubricService.Edit edit(int rev,String title){return new RubricService.Edit(title,"本课程学科说明",QualityCalculator.CODES.stream().map(code->new RubricService.Criterion(code,"学科说明 "+code,"优秀：完整依据","良好：基本可靠","合格：需补充","待改进：存在缺失")).toList(),rev);}
 long enabled(){long rid=id(draft());r.edit(1,rid,teacher(),edit(0,"课程定制量规"));r.enable(1,rid,teacher(),new RubricService.Enable(1,catalog(),"课堂目标调整"));return rid;}
 Map<String,Object> assignment(Long rubric){return domain.createAssignment(1,"量规验收","本地测试要求",Instant.now().plusSeconds(8000).toString(),false,rubric,teacher());}
 long submit(long aid){var e=domain.start(aid,student());long eid=id(e);JsonNode doc;try{doc=json.readTree("{\"type\":\"doc\",\"content\":[{\"type\":\"paragraph\",\"attrs\":{\"blockId\":\"rubric-text\"},\"content\":[{\"type\":\"text\",\"text\":\"真实非空量规验收正文\"}]}]}");}catch(Exception ex){throw new RuntimeException(ex);}domain.save(eid,new ApiController.DraftRequest("量规提交",doc,0,List.of()),student());return id(domain.submit(eid,1,"rubric-submission-test",student()));}
 void fails(int status,Runnable fn){assertEquals(status,assertThrows(ApiError.Failure.class,fn::run).status);}
 @Test void builtinIsReadableByMembersOnly()throws Exception{mvc.perform(get("/api/courses/1/rubrics")).andExpect(status().isUnauthorized());mvc.perform(get("/api/courses/1/rubrics").with(user("outsider@example.test"))).andExpect(status().isForbidden());mvc.perform(get("/api/courses/1/rubrics/four-dim-v1").with(user("student@example.test"))).andExpect(status().isOk()).andExpect(jsonPath("criteria.length()").value(11));}
 @Test void draftIsTeacherPrivate(){long rid=id(draft());assertEquals(1,((List<?>)r.list(1,student()).get("items")).size());fails(403,()->r.get(1,student(),"cr-"+rid));fails(403,()->r.history(1,student()));fails(403,()->r.create(1,student(),0L));fails(403,()->r.edit(1,rid,student(),edit(0,"非法")));fails(403,()->r.enable(1,rid,student(),new RubricService.Enable(0,0,"非法")));fails(403,()->r.setDefault(1,student(),new RubricService.Default(0L,0,"非法")));}
 @Test void assistantHasNoWriteOrDraftAccess(){long uid=s.uid("peer@example.test");s.db.update("UPDATE course_member SET role='ASSISTANT' WHERE course_id=1 AND user_id=?",uid);long rid=id(draft());fails(403,()->r.get(1,uid,"cr-"+rid));fails(403,()->r.create(1,uid,0L));fails(403,()->r.history(1,uid));enabled();assertEquals(2,((List<?>)r.list(1,uid).get("items")).size());}
 @Test void enabledCanBeReadButIsImmutable(){long rid=enabled();assertEquals("ENABLED",r.get(1,student(),"cr-"+rid).get("state"));fails(409,()->r.edit(1,rid,teacher(),edit(1,"不准覆盖")));fails(409,()->r.enable(1,rid,teacher(),new RubricService.Enable(1,catalog(),"重复")));assertEquals("课程定制量规",r.get(1,teacher(),"cr-"+rid).get("title"));}
 @Test void draftsDoNotChangeDefaultOrExistingAssignments(){draft();assertEquals("four-dim-v1",r.list(1,teacher()).get("defaultCode"));assertEquals("four-dim-v1",assignment(null).get("rubric_version"));assertEquals("four-dim-v1",domain.assignment(1).get("rubric_version"));}
 @Test void draftSaveUsesOptimisticRevision(){long rid=id(draft());r.edit(1,rid,teacher(),edit(0,"第一窗口"));fails(409,()->r.edit(1,rid,teacher(),edit(0,"旧窗口")));assertEquals("第一窗口",r.get(1,teacher(),"cr-"+rid).get("title"));}
 @Test void enableChecksBothDraftAndCatalogRevision(){long rid=id(draft());r.edit(1,rid,teacher(),edit(0,"最新"));fails(409,()->r.enable(1,rid,teacher(),new RubricService.Enable(0,0,"过期草稿")));enabled();fails(409,()->r.enable(1,rid,teacher(),new RubricService.Enable(1,0,"过期目录")));assertEquals("DRAFT",r.get(1,teacher(),"cr-"+rid).get("state"));}
 @Test void changingDefaultOnlyAffectsNewAssignments(){var before=assignment(null);long rid=enabled();assertEquals("cr-"+rid,assignment(null).get("rubric_version"));assertEquals("four-dim-v1",domain.assignment(id(before)).get("rubric_version"));r.setDefault(1,teacher(),new RubricService.Default(0L,catalog(),"回到基础"));assertEquals("four-dim-v1",assignment(null).get("rubric_version"));assertEquals("cr-"+rid,assignment(rid).get("rubric_version"));}
 @Test void explicitBuiltinWorksUnderCustomDefault(){enabled();assertEquals("four-dim-v1",assignment(0L).get("rubric_version"));}
 @Test void draftCannotBeBoundOrUsedAsCopySource(){long rid=id(draft());fails(422,()->assignment(rid));fails(422,()->r.create(1,teacher(),rid));fails(422,()->r.setDefault(1,teacher(),new RubricService.Default(rid,0,"草稿不可默认")));}
 @Test void crossCourseReferencesAreRejected(){long other=id(domain.createCourse("隔离课程","独立",teacher()));long rid=id(draft());fails(403,()->r.get(other,teacher(),"cr-"+rid));fails(403,()->r.edit(other,rid,teacher(),edit(0,"跨课程")));fails(403,()->r.create(other,teacher(),rid));fails(403,()->r.enable(other,rid,teacher(),new RubricService.Enable(0,0,"跨课程")));fails(403,()->r.setDefault(other,teacher(),new RubricService.Default(rid,0,"跨课程")));}
 @Test void validatesCompleteFixedCodesAndTexts(){var base=edit(0,"正确");var dup=new ArrayList<>(base.criteria());dup.set(0,dup.get(1));fails(422,()->r.validate(new RubricService.Edit("标题","说明",dup,0)));var unknown=new ArrayList<>(base.criteria());unknown.set(0,new RubricService.Criterion("Z1","说明","优","良","合格","改进"));fails(422,()->r.validate(new RubricService.Edit("标题","说明",unknown,0)));fails(422,()->r.validate(new RubricService.Edit(" ","说明",base.criteria(),0)));fails(422,()->r.validate(new RubricService.Edit("x".repeat(121),"说明",base.criteria(),0)));fails(422,()->r.validate(new RubricService.Edit("标题","x".repeat(2001),base.criteria(),0)));fails(422,()->r.validate(new RubricService.Edit("标题","说明",base.criteria().subList(0,10),0)));}
 @Test void blankAndOversizeAnchorsAreRejected(){for(String value:List.of(" ","x".repeat(1001))){var items=new ArrayList<>(edit(0,"标题").criteria());items.set(0,new RubricService.Criterion("S1","说明",value,"良好","合格","改进"));fails(422,()->r.validate(new RubricService.Edit("标题","说明",items,0)));}}
 @Test void canonicalNamesAndOrderRemainFixed(){long rid=id(draft());var e=edit(0,"  课程名称  ");var items=new ArrayList<>(e.criteria());Collections.reverse(items);var saved=r.edit(1,rid,teacher(),new RubricService.Edit(e.title(),e.instructions(),items,0));JsonNode criteria=(JsonNode)saved.get("criteria");assertEquals("S1",criteria.get(0).path("code").asText());assertEquals("依据可靠性",criteria.get(0).path("name").asText());assertEquals("课程名称",saved.get("title"));}
 @Test void snapshotsPinActualAssignmentNotCurrentDefault(){long rid=enabled(),aid=id(assignment(rid));enabled();long sid=submit(aid);JsonNode snap=(JsonNode)domain.getSubmission(sid,student()).get("rubricSnapshot");assertEquals("cr-"+rid,snap.path("code").asText());assertEquals("课程定制量规",snap.path("title").asText());assertEquals("学科说明 S1",snap.path("criteria").get(0).path("description").asText());assertEquals("SUBMISSION_SNAPSHOT",domain.getSubmission(sid,student()).get("rubricSnapshotSource"));}
 @Test void subsequentDefaultsCannotRewriteSnapshot(){long rid=enabled(),sid=submit(id(assignment(rid)));var before=domain.getSubmission(sid,student()).get("rubricSnapshot");r.setDefault(1,teacher(),new RubricService.Default(0L,catalog(),"切换"));assertEquals(before,domain.getSubmission(sid,student()).get("rubricSnapshot"));assertFalse(domain.getSubmission(sid,student()).containsKey("rubric_snapshot_json"));}
 @Test void legacyFallbackNeverInventsAnchors(){s.db.update("UPDATE submission SET rubric_snapshot_json=NULL WHERE id=1");JsonNode snap=(JsonNode)domain.getSubmission(1,student()).get("rubricSnapshot");assertTrue(snap.path("legacy").asBoolean());assertEquals(11,snap.path("criteria").size());assertFalse(snap.path("criteria").get(0).has("description"));assertEquals("BUILTIN_LEGACY",domain.getSubmission(1,student()).get("rubricSnapshotSource"));}
 @Test void unknownLegacyAndCorruptedSnapshotsFailClosed(){for(String packet:List.of("{}","{broken","{\"schemaVersion\":1,\"code\":\"other\"}")){s.db.update("UPDATE submission SET rubric_snapshot_json=? WHERE id=1",packet);fails(422,()->domain.getSubmission(1,student()));}s.db.update("UPDATE submission SET rubric_snapshot_json=NULL,rubric_version='unknown' WHERE id=1");fails(422,()->domain.getSubmission(1,student()));}
 @Test void enabledHistoryHasReasonsButPublicCatalogDoesNot(){long rid=enabled();var history=r.history(1,teacher());assertEquals(1,history.size());assertEquals("课堂目标调整",history.getFirst().get("reason"));assertFalse(r.list(1,student()).toString().contains("课堂目标调整"));assertEquals("cr-"+rid,history.getFirst().get("after_code"));}
 @Test void defaultsRequireReasonAndCurrentCatalog(){enabled();fails(409,()->r.setDefault(1,teacher(),new RubricService.Default(0L,0,"过期")));fails(422,()->r.setDefault(1,teacher(),new RubricService.Default(0L,catalog()," ")));fails(422,()->r.setDefault(1,teacher(),new RubricService.Default(0L,catalog(),"x".repeat(1001))));assertEquals(1,r.history(1,teacher()).size());}
 @Test void fixedCalculationStillEqualWeights(){var items=QualityCalculator.CODES.stream().map(code->new QualityCalculator.Item(code,new BigDecimal(code.startsWith("C")?"60":"80"),"SCORED","")).toList();assertEquals(0,new BigDecimal("75").compareTo(QualityCalculator.calculate(items,"").total()));}
 @Test void newEndpointsRequireCsrfAndRejectOverposting()throws Exception{mvc.perform(post("/api/courses/1/rubrics").with(user("teacher@example.test")).contentType("application/json").content("{\"sourceId\":0}")).andExpect(status().isForbidden());mvc.perform(post("/api/courses/1/rubrics").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"sourceId\":0,\"weights\":[1,0,0,0]}")).andExpect(status().isBadRequest());long rid=id(draft());mvc.perform(put("/api/courses/1/rubrics/"+rid).with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"title\":\"标题\",\"instructions\":\"说明\",\"revision\":0,\"criteria\":[]}")).andExpect(status().isBadRequest());}
 @Test void versionCountIsBoundedWithoutDeletingHistory(){for(int i=0;i<100;i++)draft();fails(422,()->draft());assertEquals(101,((List<?>)r.list(1,teacher()).get("items")).size());}
 @Test void assignmentManagementCannotRebindRubric()throws Exception{long rid=enabled();mvc.perform(put("/api/assignments/1").with(user("teacher@example.test")).with(csrf()).contentType("application/json").content("{\"title\":\"改题\",\"requirements\":\"要求\",\"dueAt\":\"2030-01-01T00:00:00Z\",\"reason\":\"调整\",\"revision\":0,\"rubricId\":"+rid+"}")).andExpect(status().isBadRequest());assertEquals("four-dim-v1",domain.assignment(1).get("rubric_version"));}
 @Test void noOpDefaultCreatesNoEvent(){fails(422,()->r.setDefault(1,teacher(),new RubricService.Default(0L,0,"无变化")));assertTrue(r.history(1,teacher()).isEmpty());}
 @Test void regradingUsesSamePinnedSnapshotAfterDefaultChanges(){long rid=enabled(),sid=submit(id(assignment(rid)));var before=domain.getSubmission(sid,teacher()).get("rubricSnapshot");enabled();var items=QualityCalculator.CODES.stream().map(code->new QualityCalculator.Item(code,new BigDecimal("82"),"SCORED","")).toList();domain.evaluate(sid,new ApiController.EvaluationRequest(items,"","本地首评",0),teacher());r.setDefault(1,teacher(),new RubricService.Default(0L,catalog(),"默认恢复"));domain.evaluate(sid,new ApiController.EvaluationRequest(items,"","本地复评",1),teacher());assertEquals(before,domain.getSubmission(sid,student()).get("rubricSnapshot"));assertEquals(2,s.db.queryForObject("SELECT COUNT(*) FROM evaluation WHERE submission_id=?",Integer.class,sid));}
 @Test void corruptedSnapshotCannotBeGraded(){s.db.update("UPDATE submission SET rubric_snapshot_json='{}' WHERE id=1");var items=QualityCalculator.CODES.stream().map(code->new QualityCalculator.Item(code,new BigDecimal("80"),"SCORED","")).toList();fails(422,()->domain.evaluate(1,new ApiController.EvaluationRequest(items,"","不得评分",1),teacher()));assertEquals(1,s.db.queryForObject("SELECT COUNT(*) FROM evaluation WHERE submission_id=1",Integer.class));}
 @Test void idempotentRetryDoesNotResnapshotNewDefault(){long rid=enabled(),aid=id(assignment(rid)),sid=submit(aid);var before=domain.getSubmission(sid,student()).get("rubricSnapshot");enabled();long eid=s.id(domain.submission(sid),"entry_id");assertEquals(sid,id(domain.submit(eid,1,"rubric-submission-test",student())));assertEquals(before,domain.getSubmission(sid,student()).get("rubricSnapshot"));}
}
